import{_ as a,o as i,c as e,a2 as r}from"./chunks/framework.BqNd1sPY.js";const l=JSON.parse('{"title":"事实核查表","description":"","frontmatter":{},"headers":[],"relativePath":"07-来源与质量审计/事实核查表.md","filePath":"07-来源与质量审计/事实核查表.md"}'),d={name:"07-来源与质量审计/事实核查表.md"};function s(m,t,n,o,k,c){return i(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="事实核查表" tabindex="-1">事实核查表 <a class="header-anchor" href="#事实核查表" aria-label="Permalink to &quot;事实核查表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>主题</th><th>容易写错的说法</th><th>本课程口径</th><th>状态</th></tr></thead><tbody><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a></td><td>“彻底取代 RNN”</td><td><a href="/LLMTrain/05-速查表/术语速查#term-transformer" class="wiki-term" data-wiki-title="Transformer" data-wiki-summary="由注意力、MLP、残差连接和归一化等模块组成的一类神经网络架构。" data-wiki-misconception="所有大模型都只能采用同一种 Transformer 结构。">Transformer</a> 是当前 LLM 主流；RNN 仍存在于其他模型和场景</td><td>已修订</td></tr><tr><td>因果<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a></td><td>“每个位置看到所有位置”</td><td>训练 Decoder LM 时<a href="/LLMTrain/05-速查表/术语速查#term-causal-mask" class="wiki-term" data-wiki-title="causal mask" data-wiki-summary="在自回归训练中阻止当前位置读取未来 token 的遮罩。" data-wiki-misconception="它会阻止模型读取当前位置之前的内容。">因果遮罩</a>禁止看到未来 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a></td><td>已修订</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>权重</td><td>“就是词的重要程度”</td><td>是特定层、头和输入下的计算权重，不能自动当作完整解释</td><td>已修订</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-qlora" class="wiki-term" data-wiki-title="QLoRA" data-wiki-summary="以低比特形式保存冻结的基础模型，同时训练 LoRA 适配器。" data-wiki-misconception="LoRA 适配器本身被简单量化成 4 bit。">QLoRA</a></td><td>“4-bit 所以总显存减少 75%”</td><td>4-bit 针对冻结基础权重；总显存还含激活、<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>和<a href="/LLMTrain/05-速查表/术语速查#term-optimizer" class="wiki-term" data-wiki-title="optimizer" data-wiki-summary="根据梯度及内部状态计算参数更新的算法，例如 AdamW。" data-wiki-misconception="优化器负责计算前向预测或损失。">优化器</a>状态</td><td>已修订</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a></td><td>“越低模型越好”</td><td>仅在相同数据、tokenization 和计算方式下比较；还需<a href="/LLMTrain/05-速查表/术语速查#term-validation-set" class="wiki-term" data-wiki-title="validation set" data-wiki-summary="不参与梯度更新、用于选择配置和观察泛化表现的数据。" data-wiki-misconception="反复针对验证集调参不会产生信息泄漏。">验证集</a>和任务指标</td><td>已修订</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>量</td><td>“越大一定越好”</td><td>能力取决于数据、训练计算、架构、后训练和评测条件</td><td>已修订</td></tr><tr><td><a href="/LLMTrain/05-速查表/术语速查#term-rag" class="wiki-term" data-wiki-title="RAG" data-wiki-summary="先检索外部资料，再把相关片段放进上下文辅助生成。" data-wiki-misconception="检索到资料就能保证资料和答案都真实。">RAG</a>/微调</td><td>“加入新知识就微调”</td><td>频繁变化或需引用的知识通常先考虑检索；微调更适合行为和格式</td><td>已修订</td></tr><tr><td>训练/<a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a></td><td>“生成时还在学习”</td><td>常规<a href="/LLMTrain/05-速查表/术语速查#term-inference" class="wiki-term" data-wiki-title="inference" data-wiki-summary="使用训练好的参数，根据输入计算预测或生成结果。" data-wiki-misconception="推理阶段通常会继续更新模型权重。">推理</a>不会更新<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>；<a href="/LLMTrain/05-速查表/术语速查#term-context" class="wiki-term" data-wiki-title="context" data-wiki-summary="模型本次计算能够看到的 token 序列。" data-wiki-misconception="放进上下文的信息已经永久写入模型参数。">上下文</a>变化不等于权重学习</td><td>已修订</td></tr></tbody></table>',2)])])}const L=a(d,[["render",s]]);export{l as __pageData,L as default};
